    def dataGrab(self):
        data = ui.vector_data#Ui_MainWindow.vectorSetup(ui, ui.symmetryValue.value(), ui.shiftSelect.currentIndex())
        data[:,3] = np.round(data[:,3],3)
        self.model = TableModel(data,['Tile scale','Grid scale','Angle','Grid shift'])
